def notify_roles_to_rules(apps, schema_editor):
    """
    Turn each ``Transition.notify_roles`` entry into a ``NotificationRule``.

    ``notify_roles`` was resolved against every group with access to the record,
    so the rule keeps that reach (``instance_groups``) rather than silently
    narrowing or widening who is told. An administrator can tighten a rule to the
    ``custodian`` scope afterwards.
    """
    Transition = apps.get_model("pwms", "Transition")
    NotificationRule = apps.get_model("pwms", "NotificationRule")
    for transition in Transition.objects.prefetch_related("notify_roles"):
        for role in transition.notify_roles.all():
            NotificationRule.objects.get_or_create(
                workflow_type_id=transition.workflow_type_id,
                event="transition",
                transition_id=transition.pk,
                role_id=role.pk,
                defaults={"scope": "instance_groups", "channel": "both"},
            )


def rules_to_notify_roles(apps, schema_editor):
    """Reverse: put per-transition role rules back into ``notify_roles``."""
    NotificationRule = apps.get_model("pwms", "NotificationRule")
    rules = NotificationRule.objects.filter(
        event="transition", transition__isnull=False, role__isnull=False
    ).select_related("transition")
    for rule in rules:
        rule.transition.notify_roles.add(rule.role_id)


